input.command:
C=$(cat container_name3) && cat > /tmp/probe.groovy <<'EOF'
pipeline {
  agent any
  parameters {
    string(name: 'GIT_URL', defaultValue: 'https://github.com/Tuchsanai/DevTools.git', description: '')
    string(name: 'APP_VERSION', defaultValue: '1.0.0', description: '')
  }
  stages { stage('P') { steps { echo "params.GIT_URL=${params.GIT_URL} params.APP_VERSION=${params.APP_VERSION}" } } }
}
EOF
docker cp /tmp/probe.groovy $C:/tmp/probe.groovy && docker exec $C bash -c '
J=http://localhost:8080; A="$(cat /root/.jauth)"; JAR=/tmp/pjar
cr=$(curl -s -u "$A" -c $JAR -b $JAR $J/crumbIssuer/api/json | python3 -c "import json,sys;d=json.load(sys.stdin);print(d[\"crumbRequestField\"]+\":\"+d[\"crumb\"])")
S=$(python3 -c "import html;print(html.escape(open(\"/tmp/probe.groovy\").read()),end=\"\")")
printf "<flow-definition><definition class=\"org.jenkinsci.plugins.workflow.cps.CpsFlowDefinition\"><script>%s</script><sandbox>true</sandbox></definition></flow-definition>" "$S" > /tmp/probe.xml
echo create $(curl -s -u "$A" -c $JAR -b $JAR -H "$cr" -o /dev/null -w "%{http_code}" -X POST -H "Content-Type: application/xml" --data-binary @/tmp/probe.xml "$J/createItem?name=zz-params-probe")
echo build $(curl -s -u "$A" -c $JAR -b $JAR -H "$cr" -o /dev/null -w "%{http_code}" -X POST "$J/job/zz-params-probe/build")
for i in $(seq 40); do curl -sf -u "$A" "$J/job/zz-params-probe/1/api/json?tree=building" 2>/dev/null | grep -q "\"building\":false" && break; sleep 2; done
curl -s -u "$A" "$J/job/zz-params-probe/1/consoleText" | grep -E "params\.|Finished"
echo delete $(curl -s -u "$A" -c $JAR -b $JAR -H "$cr" -o /dev/null -w "%{http_code}" -X POST "$J/job/zz-params-probe/doDelete")
rm -f /tmp/probe.xml /tmp/probe.groovy $JAR' | tee out3/params-probe.txt

